(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-113":{scenario:{legacy:"B"},learning:{summary:{vi:"Kế toán công nợ phải thu, phải trả theo dõi toàn bộ quan hệ thanh toán với khách hàng và nhà cung cấp: đối chiếu ba chiều đơn mua - phiếu nhập - hóa đơn trước khi thanh toán, lập lịch chi theo hạn, theo dõi tuổi nợ, đối chiếu công nợ định kỳ, trích lập dự phòng nợ khó đòi và phối hợp thu hồi nợ. Giá trị tạo ra là dòng tiền lành mạnh, không chi trùng, không chi sai, không để nợ quá hạn kéo dài.",en:"An AR/AP specialist manages all payment relationships with customers and suppliers: three-way matching of purchase order, goods receipt and invoice before payment, scheduling payments by due date, tracking aging, running periodic balance confirmations, providing for doubtful debts and supporting collections. The value is healthy cash flow, no duplicate or wrong payments and no long-overdue receivables."},responsibilities:{vi:["Đối chiếu ba chiều đơn mua, phiếu nhập kho và hóa đơn trước khi đề nghị thanh toán.","Lập lịch thanh toán nhà cung cấp theo hạn, điều khoản chiết khấu và kế hoạch dòng tiền.","Theo dõi tuổi nợ phải thu, nhắc nợ và phối hợp kinh doanh thu hồi khoản quá hạn.","Gửi và đối chiếu biên bản xác nhận công nợ định kỳ, xử lý chênh lệch.","Đề xuất trích lập dự phòng nợ phải thu khó đòi và đánh giá lại công nợ gốc ngoại tệ."],en:["Three-way match purchase orders, goods receipts and invoices before requesting payment.","Schedule supplier payments by due date, discount terms and the cash plan.","Track receivable aging, send reminders and work with Sales to collect overdue items.","Send and reconcile periodic balance confirmations and resolve differences.","Propose doubtful debt provisions and revalue foreign currency balances."]},competencies:[{name:{vi:"Đối chiếu ba chiều",en:"Three-way matching"},desc:{vi:"So khớp số lượng, đơn giá, thuế và tổng tiền giữa đơn mua, phiếu nhập và hóa đơn.",en:"Match quantity, unit price, tax and totals across the PO, goods receipt and invoice."}},{name:{vi:"Quản lý tuổi nợ",en:"Aging management"},desc:{vi:"Phân nhóm nợ theo thời gian quá hạn, ưu tiên thu hồi và cảnh báo rủi ro tín dụng.",en:"Bucket balances by days overdue, prioritize collection and flag credit risk."}},{name:{vi:"Đối chiếu công nợ",en:"Balance confirmation"},desc:{vi:"Lập biên bản xác nhận, truy vết chênh lệch do hóa đơn, thanh toán hoặc trả hàng chưa ghi.",en:"Issue confirmations and trace gaps from unrecorded invoices, payments or returns."}},{name:{vi:"Kiểm soát thanh toán",en:"Payment control"},desc:{vi:"Ngăn chi trùng, chi sai tài khoản và thay đổi thông tin ngân hàng nhà cung cấp chưa xác minh.",en:"Prevent duplicate payments, wrong accounts and unverified supplier bank changes."}},{name:{vi:"Chính trực & phân tách nhiệm vụ",en:"Integrity & segregation"},desc:{vi:"Không duyệt hóa đơn chưa khớp theo áp lực, giữ tách bạch người lập, người duyệt, người chi.",en:"Never approve unmatched invoices under pressure; keep preparer, approver and payer separate."}}],knowledge:{vi:["Thông tư 48/2019/TT-BTC về dự phòng: nợ quá hạn từ 6 tháng đến dưới 1 năm trích 30%, 1 đến dưới 2 năm 50%, 2 đến dưới 3 năm 70%, từ 3 năm trở lên 100%.","Hạch toán TK 131 phải thu khách hàng và TK 331 phải trả người bán theo chế độ kế toán doanh nghiệp (Thông tư 200/2014/TT-BTC và văn bản thay thế).","VAS 10 về ảnh hưởng của thay đổi tỷ giá: đánh giá lại số dư công nợ gốc ngoại tệ cuối kỳ.","Nghị định 123/2020/NĐ-CP về hóa đơn điện tử, hóa đơn điều chỉnh và thay thế.","Nguyên tắc kiểm soát nội bộ: phân tách nhiệm vụ, phê duyệt theo hạn mức, đối chiếu độc lập."],en:["Circular 48/2019/TT-BTC on provisions: overdue 6 months to under 1 year 30%, 1 to under 2 years 50%, 2 to under 3 years 70%, 3 years or more 100%.","Accounts 131 trade receivables and 331 trade payables under the enterprise accounting regime (Circular 200/2014/TT-BTC and its replacement).","VAS 10 on exchange rate effects: revaluing foreign currency receivable and payable balances at period end.","Decree 123/2020/ND-CP on e-invoices, adjusting and replacement invoices.","Internal control principles: segregation of duties, approval limits and independent reconciliation."]},tools:["Phần mềm kế toán (ERP) phân hệ công nợ","Hệ thống hóa đơn điện tử","Ngân hàng điện tử","Microsoft Excel","Công cụ nhắc nợ tự động qua email"],kpis:{vi:["Số ngày thu tiền bình quân (DSO) và số ngày trả tiền bình quân (DPO).","Tỷ lệ nợ phải thu quá hạn trên 90 ngày.","Số lần chi trùng hoặc chi sai (mục tiêu bằng 0).","Tỷ lệ khách hàng, nhà cung cấp lớn đã xác nhận công nợ cuối kỳ."],en:["Days sales outstanding (DSO) and days payable outstanding (DPO).","Share of receivables more than 90 days overdue.","Duplicate or wrong payments (target zero).","Share of key customers and suppliers confirming period-end balances."]},day:[{time:"08:00",vi:"Kiểm tra tiền về tài khoản, cấn trừ các khoản khách hàng đã thanh toán.",en:"Check incoming funds and apply customer payments to open invoices."},{time:"09:30",vi:"Đối chiếu ba chiều các hóa đơn nhà cung cấp mới và trả lại hồ sơ chưa khớp.",en:"Three-way match new supplier invoices and return unmatched files."},{time:"13:30",vi:"Lập lịch thanh toán tuần, trình duyệt theo hạn mức và kế hoạch dòng tiền.",en:"Prepare the weekly payment run and submit for approval by limits and cash plan."},{time:"15:00",vi:"Gọi nhắc nợ khách hàng quá hạn, cập nhật cam kết thanh toán vào hệ thống.",en:"Call overdue customers and log payment promises in the system."},{time:"16:30",vi:"Cập nhật báo cáo tuổi nợ, đề xuất dự phòng và gửi biên bản đối chiếu công nợ.",en:"Update the aging report, propose provisions and send balance confirmations."}],mistakes:{vi:["Thanh toán theo hóa đơn khi số lượng chưa khớp phiếu nhập kho, dẫn tới trả thừa tiền.","Đổi tài khoản ngân hàng nhà cung cấp theo email mà không gọi xác minh độc lập, bị lừa đảo chuyển tiền.","Không trích lập dự phòng cho khoản nợ quá hạn lâu, làm tài sản và lợi nhuận bị phản ánh cao hơn thực tế."],en:["Paying an invoice whose quantity does not match the goods receipt, causing overpayment.","Changing supplier bank details from an email without independent call-back, enabling payment fraud.","Not providing for long-overdue debts, overstating assets and profit."]},career:[{vi:"Nhân viên kế toán công nợ",en:"AR/AP clerk"},{vi:"Chuyên viên kế toán công nợ",en:"AR/AP specialist"},{vi:"Trưởng nhóm thu chi & tín dụng",en:"Credit & payments team lead"},{vi:"Kế toán tổng hợp / Quản lý ngân quỹ",en:"General accountant / Treasury manager"}],glossary:[{term:"Three-way match",vi:"Đối chiếu ba chiều giữa đơn mua, phiếu nhập kho và hóa đơn trước khi duyệt thanh toán.",en:"Matching the purchase order, goods receipt and invoice before approving payment."},{term:"Aging",vi:"Báo cáo tuổi nợ phân nhóm số dư theo số ngày chưa thanh toán hoặc quá hạn.",en:"A report grouping balances by days outstanding or overdue."},{term:"DSO",vi:"Số ngày thu tiền bình quân = phải thu bình quân / doanh thu bán chịu x số ngày trong kỳ.",en:"Days sales outstanding = average receivables / credit sales x days in the period."},{term:"Dự phòng nợ khó đòi",vi:"Khoản ước tính tổn thất của nợ phải thu có khả năng không thu hồi, ghi giảm tài sản và tăng chi phí.",en:"Doubtful debt provision: estimated loss on receivables unlikely to be collected, reducing assets."},{term:"Credit note",vi:"Chứng từ ghi giảm khoản phải thu hoặc phải trả do giảm giá, trả lại hàng hoặc điều chỉnh.",en:"A document reducing a receivable or payable for discounts, returns or adjustments."}],quiz:[{q:{vi:"Khoản phải thu 200 triệu đồng đã quá hạn 14 tháng, chưa trích dự phòng. Theo Thông tư 48/2019/TT-BTC, mức dự phòng là bao nhiêu?",en:"A VND 200 million receivable is 14 months overdue with no provision yet. Under Circular 48/2019/TT-BTC, what is the provision?"},options:{vi:["60 triệu đồng","140 triệu đồng","200 triệu đồng","100 triệu đồng"],en:["VND 60 million","VND 140 million","VND 200 million","VND 100 million"]},answer:3,explain:{vi:"Quá hạn từ 1 năm đến dưới 2 năm trích 50%: 200 x 50% = 100 triệu đồng.",en:"Overdue 1 to under 2 years requires 50%: 200 x 50% = VND 100 million."}},{q:{vi:"Hóa đơn ghi 128 đơn vị nhưng phiếu nhập kho chỉ có 120. Bạn xử lý thế nào?",en:"The invoice shows 128 units but the goods receipt shows 120. What do you do?"},options:{vi:["Thanh toán đủ 128 vì đã có hóa đơn","Tạm dừng, yêu cầu nhà cung cấp điều chỉnh hóa đơn theo số lượng thực nhận","Thanh toán 128 rồi trừ vào lần sau","Sửa phiếu nhập cho khớp hóa đơn"],en:["Pay 128 since there is an invoice","Hold it and ask the supplier to adjust the invoice to the received quantity","Pay 128 and offset next time","Change the receipt to match the invoice"]},answer:1,explain:{vi:"Chỉ thanh toán theo số lượng thực nhận đã được xác nhận; hóa đơn sai phải được điều chỉnh.",en:"Pay only for confirmed received quantities; the wrong invoice must be adjusted."}},{q:{vi:"Nhận email đổi số tài khoản ngân hàng từ nhà cung cấp ngay trước kỳ thanh toán. Bước đúng tiếp theo là gì?",en:"An email asks to change a supplier's bank account just before a payment run. What is the right next step?"},options:{vi:["Gọi xác minh qua số điện thoại đã lưu trong hồ sơ và trình duyệt thay đổi","Cập nhật ngay để kịp thanh toán","Chuyển thử một khoản nhỏ vào tài khoản mới","Hỏi lại qua chính email đó"],en:["Call back on the phone number on file and get the change approved","Update it at once to pay on time","Send a small test payment to the new account","Reply to the same email to confirm"]},answer:0,explain:{vi:"Xác minh độc lập qua kênh đã lưu trước đó là kiểm soát chống lừa đảo thay đổi thông tin thanh toán.",en:"Independent call-back through a known channel is the key control against payment diversion fraud."}},{q:{vi:"Quản lý yêu cầu duyệt hóa đơn chưa khớp đơn mua ngay hôm nay rồi điều chỉnh hồ sơ sau. Phương án đúng là gì?",en:"A manager asks you to approve an invoice that does not match the PO today and fix the records later. What is right?"},options:{vi:["Duyệt vì quản lý đã yêu cầu","Duyệt một phần cho kịp","Từ chối, đối chiếu đơn mua đã duyệt và yêu cầu hóa đơn điều chỉnh","Chờ cuối tháng rồi tính"],en:["Approve because the manager asked","Approve part of it to save time","Refuse, reconcile with the approved PO and request a corrected invoice","Wait until month end"]},answer:2,explain:{vi:"Duyệt hóa đơn chưa khớp làm mất kiểm soát chi; phải đối chiếu và có chứng từ điều chỉnh trước.",en:"Approving unmatched invoices breaks payment control; reconcile and obtain a corrected document first."}}],tools_en:["ERP accounting software - AR/AP module","E-invoicing system","Online banking","Microsoft Excel","Automated email dunning tools"]}}})})(window.KKR);
